// M3 - Check Idempotency (RFC-089 §5.3)
// Vérifie si une requête avec cette idempotency_key est déjà en cours ou terminée

const input = $input.first().json;
const body = input.body || {};
const idempotencyKey = body.idempotency_key;

// Si pas d'idempotency_key, continuer normalement (backward compat)
if (!idempotencyKey) {
  return [{ json: { ...input, idempotency: { enabled: false } } }];
}

// Clé Redis pour l'idempotence
const redisKey = `idempotency:classroom-sync:${idempotencyKey}`;

// Note: En production, utiliser le node Redis
// Pour l'instant, on stocke dans staticData (limité mais fonctionnel)
const staticData = $getWorkflowStaticData('global');
const cache = staticData.idempotencyCache || {};
const now = Date.now();
const TTL_MS = 30 * 60 * 1000; // 30 minutes

// Nettoyer les entrées expirées
for (const key of Object.keys(cache)) {
  if (cache[key].expiresAt < now) {
    delete cache[key];
  }
}

// Vérifier si la clé existe
const existing = cache[idempotencyKey];

if (existing) {
  if (existing.status === 'processing') {
    // Opération en cours - retourner 409 Conflict
    return [{
      json: {
        idempotency: {
          enabled: true,
          hit: true,
          status: 'processing',
          conflict: true,
          message: 'Operation already in progress for this idempotency_key'
        }
      }
    }];
  } else if (existing.status === 'completed') {
    // Résultat cached - retourner le résultat précédent
    return [{
      json: {
        idempotency: {
          enabled: true,
          hit: true,
          status: 'completed',
          cachedResult: existing.result
        }
      }
    }];
  }
}

// Nouvelle requête - marquer comme "processing"
cache[idempotencyKey] = {
  status: 'processing',
  startedAt: new Date().toISOString(),
  expiresAt: now + TTL_MS
};
staticData.idempotencyCache = cache;

return [{
  json: {
    ...input,
    idempotency: {
      enabled: true,
      hit: false,
      key: idempotencyKey
    }
  }
}];

// M5 - Validate Headers (RFC-089 §5.4)
// Lit X-Google-Access-Token et valide X-Webhook-Secret

const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};

// Récupérer le secret attendu depuis les variables d'environnement
const expectedSecret = $env.MCP_WEBHOOK_SECRET || '';

// Lire le token depuis le header (M5) avec fallback sur body (backward compat)
const accessToken = headers['x-google-access-token'] || headers['X-Google-Access-Token'] || body.access_token;

// Valider le webhook secret si configuré
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';

let validation = {
  valid: true,
  errors: []
};

// Validation du secret (si configuré)
if (expectedSecret && providedSecret !== expectedSecret) {
  validation.valid = false;
  validation.errors.push('Invalid or missing X-Webhook-Secret header');
}

// Validation du token
if (!accessToken) {
  validation.valid = false;
  validation.errors.push('Missing access_token (provide via X-Google-Access-Token header or body.access_token)');
}

// Validation des champs requis du body
if (!body.expert_response_id) {
  validation.valid = false;
  validation.errors.push('Missing required field: expert_response_id');
}
if (!body.course_id) {
  validation.valid = false;
  validation.errors.push('Missing required field: course_id');
}
if (!body.programme) {
  validation.valid = false;
  validation.errors.push('Missing required field: programme');
}

return [{
  json: {
    ...input,
    body: {
      ...body,
      access_token: accessToken  // Normaliser le token dans le body
    },
    validation,
    headers_secured: {
      token_from_header: !!headers['x-google-access-token'] || !!headers['X-Google-Access-Token'],
      secret_validated: expectedSecret ? (providedSecret === expectedSecret) : 'not_configured'
    }
  }
}];

// Initialiser le contexte de synchronisation
const input = $input.first().json;
const body = input.body;

const context = {
  expert_response_id: body.expert_response_id,
  course_id: body.course_id,
  tenant_id: body.tenant_id || 'default',
  access_token: body.access_token,
  callback_url: body.callback_url || null,
  webhook_base_url: $env.N8N_WEBHOOK_BASE_URL || 'http://localhost:5678/webhook',
  idempotency_key: input.idempotency?.key || null
};

const sequences = body.programme.architecture || [];
const sessions = body.programme.progression || [];

// M7 - Calculer si on doit passer en mode async
const totalOperations = sequences.length + sessions.length;
const ASYNC_THRESHOLD = 20;
const shouldBeAsync = totalOperations > ASYNC_THRESHOLD;

return [{
  json: {
    context,
    sequences,
    sessions,
    current_sequence_index: 0,
    current_session_index: 0,
    results: {
      topic_mapping: {},
      topic_ids: [],
      coursework_ids: [],
      errors: []
    },
    stats: {
      total_sequences: sequences.length,
      total_sessions: sessions.length,
      total_operations: totalOperations,
      started_at: new Date().toISOString()
    },
    phase: 'topics',
    async_mode: shouldBeAsync,
    task_id: shouldBeAsync ? `task-${Date.now()}-${Math.random().toString(36).substr(2, 9)}` : null
  }
}];

// M7 - Stocker le task en cours et préparer la réponse 202
const data = $input.first().json;

// Stocker dans staticData pour le worker async
const staticData = $getWorkflowStaticData('global');
const tasks = staticData.asyncTasks || {};

tasks[data.task_id] = {
  status: 'pending',
  context: data.context,
  sequences: data.sequences,
  sessions: data.sessions,
  stats: data.stats,
  createdAt: new Date().toISOString(),
  expiresAt: Date.now() + (60 * 60 * 1000) // 1h TTL
};

staticData.asyncTasks = tasks;

return [{
  json: {
    task_id: data.task_id,
    status: 'processing',
    message: `Operation queued for async processing (${data.stats.total_operations} operations > threshold ${20})`,
    poll_url: `${data.context.webhook_base_url}/classroom-sync-status?task_id=${data.task_id}`,
    estimated_duration_seconds: Math.ceil(data.stats.total_operations * 0.5)
  }
}];

// M6 - Rate Limit Check (RFC-089 §5.5)
// Token bucket: 50 ops/s par tenant

const data = $input.first().json;
const tenantId = data.context.tenant_id || 'default';

// Utiliser staticData comme cache de rate-limit (en prod: Redis)
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};
const now = Date.now();
const windowKey = `${tenantId}:${Math.floor(now / 1000)}`;

// Initialiser ou incrémenter le compteur
if (!rateLimits[windowKey]) {
  rateLimits[windowKey] = { count: 0, expiresAt: now + 2000 };
}
rateLimits[windowKey].count++;

// Nettoyer les anciennes fenêtres
for (const key of Object.keys(rateLimits)) {
  if (rateLimits[key].expiresAt < now) {
    delete rateLimits[key];
  }
}
staticData.rateLimits = rateLimits;

const count = rateLimits[windowKey].count;
const LIMIT = 50;

let rateLimitInfo = {
  current_count: count,
  limit: LIMIT,
  window: windowKey,
  throttled: false,
  delay_ms: 0
};

// Si on dépasse la limite, calculer le délai
if (count > LIMIT) {
  const delay = Math.min((count - LIMIT) * 20, 5000); // max 5s
  rateLimitInfo.throttled = true;
  rateLimitInfo.delay_ms = delay;

  // Note: En production, implémenter un vrai sleep ou utiliser le node Wait
  // Pour l'instant on log juste le throttling
}

// Préparer la requête pour créer le topic courant
const idx = data.current_sequence_index;
const sequence = data.sequences[idx];
const topicName = sequence.titre || sequence.title || `Séquence ${sequence.id || (idx + 1)}`;

return [{
  json: {
    ...data,
    current_sequence: sequence,
    rate_limit: rateLimitInfo,
    mcp_request: {
      access_token: data.context.access_token,
      resource: 'topic',
      operation: 'create',
      course_id: data.context.course_id,
      name: topicName
    }
  }
}];

// Traiter la réponse de création du topic et incrémenter l'index
const prevData = $('Rate Limit + Prepare Topic').first().json;
const mcpResponse = $input.first().json;

const data = { ...prevData };
const sequenceId = data.current_sequence.id || String(data.current_sequence_index);

// Extraire l'ID du topic créé
const topicData = mcpResponse.data || mcpResponse;
const topicId = topicData.topicId || topicData.id;

if (topicId && mcpResponse.success !== false) {
  data.results.topic_mapping[sequenceId] = topicId;
  data.results.topic_ids.push(topicId);
} else {
  data.results.errors.push({
    type: 'topic_creation_failed',
    sequence_id: sequenceId,
    sequence_name: data.current_sequence.titre || data.current_sequence.title,
    error: mcpResponse.error || topicData.error || 'Unknown error'
  });
}

// Incrémenter l'index pour la prochaine itération
data.current_sequence_index = data.current_sequence_index + 1;
delete data.current_sequence;
delete data.mcp_request;
delete data.rate_limit;

return [{ json: data }];

// M6 - Rate Limit + Préparer la requête pour créer le courseWork courant
const data = $input.first().json;
const tenantId = data.context.tenant_id || 'default';

// Rate limit check (même logique que pour les topics)
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};
const now = Date.now();
const windowKey = `${tenantId}:${Math.floor(now / 1000)}`;

if (!rateLimits[windowKey]) {
  rateLimits[windowKey] = { count: 0, expiresAt: now + 2000 };
}
rateLimits[windowKey].count++;
staticData.rateLimits = rateLimits;

const idx = data.current_session_index;
const session = data.sessions[idx];

// Trouver le topicId associé via sequence_id
const sequenceId = session.sequence_id || null;
const topicId = sequenceId ? (data.results.topic_mapping[sequenceId] || null) : null;

// Construire la description enrichie
let description = session.description || '';
if (session.objectifs && Array.isArray(session.objectifs) && session.objectifs.length > 0) {
  description += '\n\nObjectifs pédagogiques:\n' + session.objectifs.map(o => `• ${o}`).join('\n');
}
if (session.duree_minutes) {
  description += `\n\nDurée estimée: ${session.duree_minutes} minutes`;
}

const courseWorkTitle = session.titre || session.title || `Séance ${session.id || (idx + 1)}`;

return [{
  json: {
    ...data,
    current_session: session,
    mcp_request: {
      access_token: data.context.access_token,
      resource: 'courseWork',
      operation: 'create',
      course_id: data.context.course_id,
      title: courseWorkTitle,
      description: description.trim(),
      work_type: session.work_type || 'ASSIGNMENT',
      state: 'DRAFT',
      topic_id: topicId
    }
  }
}];

// Traiter la réponse de création du courseWork et incrémenter l'index
const prevData = $('Rate Limit + Prepare CourseWork').first().json;
const mcpResponse = $input.first().json;

const data = { ...prevData };
const sessionId = data.current_session.id || String(data.current_session_index);

// Extraire l'ID du courseWork créé
const cwData = mcpResponse.data || mcpResponse;
const courseWorkId = cwData.id;

if (courseWorkId && mcpResponse.success !== false) {
  data.results.coursework_ids.push({
    session_id: sessionId,
    coursework_id: courseWorkId,
    sequence_id: data.current_session.sequence_id || null,
    topic_id: data.mcp_request.topic_id,
    title: data.mcp_request.title
  });
} else {
  data.results.errors.push({
    type: 'coursework_creation_failed',
    session_id: sessionId,
    session_title: data.current_session.titre || data.current_session.title,
    error: mcpResponse.error || cwData.error || 'Unknown error'
  });
}

// Incrémenter l'index pour la prochaine itération
data.current_session_index = data.current_session_index + 1;
delete data.current_session;
delete data.mcp_request;

return [{ json: data }];

// Préparer le payload de callback
const data = $input.first().json;

return [{
  json: {
    ...data,
    callback_payload: {
      expert_response_id: data.context.expert_response_id,
      course_id: data.context.course_id,
      topic_ids: data.results.topic_ids,
      coursework_ids: data.results.coursework_ids.map(c => c.coursework_id),
      topic_mapping: data.results.topic_mapping,
      detailed_coursework: data.results.coursework_ids,
      errors: data.results.errors,
      synced_at: new Date().toISOString()
    }
  }
}];

// Préparer la réponse finale après callback
const prevData = $('Prepare Callback Payload').first().json;

return [{
  json: {
    ...prevData,
    callback_sent: true
  }
}];

// Marquer qu'il n'y a pas de callback
const data = $input.first().json;

return [{
  json: {
    ...data,
    callback_sent: false
  }
}];

// Préparer la réponse finale
const data = $input.first().json;

const hasErrors = data.results.errors.length > 0;
const partialSuccess = hasErrors && (data.results.topic_ids.length > 0 || data.results.coursework_ids.length > 0);

const response = {
  success: !hasErrors,
  partial_success: partialSuccess,
  data: {
    expert_response_id: data.context.expert_response_id,
    course_id: data.context.course_id,
    topics_created: data.results.topic_ids.length,
    coursework_created: data.results.coursework_ids.length,
    topic_ids: data.results.topic_ids,
    coursework_ids: data.results.coursework_ids.map(c => c.coursework_id),
    topic_mapping: data.results.topic_mapping,
    detailed_coursework: data.results.coursework_ids,
    callback_sent: data.callback_sent,
    synced_at: new Date().toISOString(),
    stats: {
      ...data.stats,
      completed_at: new Date().toISOString(),
      topics_requested: data.stats.total_sequences,
      sessions_requested: data.stats.total_sessions,
      errors_count: data.results.errors.length
    }
  }
};

if (hasErrors) {
  response.errors = data.results.errors;
}

return [{ json: { response, idempotency_key: data.context.idempotency_key } }];

// M3 - Store Result in Idempotency Cache (RFC-089 §5.3)
// Stocker le résultat pour les futures requêtes avec la même clé

const data = $input.first().json;
const idempotencyKey = data.idempotency_key;

if (idempotencyKey) {
  const staticData = $getWorkflowStaticData('global');
  const cache = staticData.idempotencyCache || {};

  if (cache[idempotencyKey]) {
    cache[idempotencyKey].status = 'completed';
    cache[idempotencyKey].result = data.response;
    cache[idempotencyKey].completedAt = new Date().toISOString();
  }

  staticData.idempotencyCache = cache;
}

return [{ json: data.response }];
